/**
 * Identifies the build these constants and the CApi functions describe.
 *
 * The 32-bit FNV-1a hash (offset basis 0x811c9dc5, prime 0x01000193) of these
 * bytes, which a loader reads from the instance and the compiled module:
 *
 * 1. The string `sqlite3__wasm_enum_json()` returns: its UTF-8 bytes including the
 *    terminating NUL.
 * 2. The name of every export `WebAssembly.Module.exports` lists, in the order
 *    `toSorted()` without a comparator gives: for each, its UTF-8 bytes
 *    followed by a NUL byte.
 *
 * The string holds SQLite's version and check-in, every constant and the struct
 * layouts, and the names include every function and shim the CApi module reads.
 * The hash covers neither code nor function types; the generator checks every
 * binding's and shim's wasm type against the pinned build, and
 * `scripts/generate.mts --verify-build` checks a binary against the pins.
 */
export const sqliteWasmBuildHash = 0xc5cfb5b8;
